@Audited                                          // @InterceptorBinding
@Interceptor
public class AuditInterceptor {
    @Inject AuditSink sink;
    @AroundInvoke
    Object audit(InvocationContext ctx) throws Exception {
        AuditEvent ev = new AuditEvent(subject(), ctx.getMethod().getName(), "attempt");
        sink.record(ev);
        try { Object r = ctx.proceed(); sink.record(ev.succeeded()); return r; }
        catch (Exception e) { sink.record(ev.failed(e)); throw e; }
    }
}

